import limited_client as robot, numpy as np
for c in (0,2):
 o=robot.observe(camera=c); r=o['robot']; print('camera',c,'tcp',r['tcp_position'],'joints',r['joint_positions'],'gripper',r['gripper_positions'])
 if c==2:
  rgb=o['rgb'].astype(int); d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']
  # Candidate compact gray object pixels: low chroma, mid-gray, above table.
  mask=(rgb[:,:,0]>45)&(rgb[:,:,0]<145)&(np.abs(rgb[:,:,0]-rgb[:,:,1])<15)&(np.abs(rgb[:,:,1]-rgb[:,:,2])<15)&(d<1.45)
  H,W=mask.shape; seen=np.zeros_like(mask); comps=[]
  for y,x in zip(*np.where(mask)):
   if seen[y,x]: continue
   stack=[(y,x)]; seen[y,x]=1; pts=[]
   while stack:
    yy,xx=stack.pop(); pts.append((yy,xx))
    for ny,nx in ((yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)):
     if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]: seen[ny,nx]=1; stack.append((ny,nx))
   if len(pts)>20:
    ys,xs=np.array(pts).T; cy,cx=float(ys.mean()),float(xs.mean()); z=float(np.median(d[ys,xs])); p=np.array([(cx-K[0,2])*z/K[0,0],(cy-K[1,2])*z/K[1,1],z,1]); comps.append((len(pts),(xs.min(),ys.min(),xs.max(),ys.max()),(cx,cy),z,(T@p)[:3],rgb[int(cy),int(cx)].tolist()))
  print('gray components',sorted(comps,reverse=True)[:20])
  pc=np.linalg.inv(T)@np.array(r['tcp_position']+[1]); q=K@pc[:3]; print('tcp pixel',q[:2]/q[2])
print('status',robot.status())
